  1	// Meeting-room booking server: JSON API + static page, data kept in one JSON file.
  2	// Node.js built-ins only. Run with `node server.mjs`.
  3	import http from 'node:http';
  4	import { readFileSync } from 'node:fs';
  5	import { readFile, writeFile } from 'node:fs/promises';
  6	import path from 'node:path';
  7	
  8	const HOST = '127.0.0.1';
  9	const DEFAULT_PORT = 3000;
 10	const DEFAULT_DATA_FILE = 'bookings.json';
 11	const MAX_BODY_BYTES = 10000;
 12	const ROOMS = Object.freeze(['Aurora', 'Borealis', 'Cosmos']);
 13	const JSON_TYPE = 'application/json; charset=utf-8';
 14	const BOOKINGS_PREFIX = '/api/bookings/';
 15	const BOOKING_KEYS = Object.freeze(['id', 'room', 'title', 'date', 'start', 'end']);
 16	const STATIC_FILES = Object.freeze({
 17	  '/': { url: new URL('./public/index.html', import.meta.url), type: 'text/html; charset=utf-8' },
 18	  '/app.js': { url: new URL('./public/app.js', import.meta.url), type: 'text/javascript; charset=utf-8' },
 19	});
 20	
 21	const MSG = Object.freeze({
 22	  notFound: 'not found',
 23	  method: 'method not allowed',
 24	  internal: 'internal error',
 25	  bookingNotFound: 'booking not found',
 26	  contentType: 'content type must be application/json',
 27	  tooLarge: 'body too large',
 28	  notObject: 'body must be a JSON object',
 29	  room: `room must be one of ${ROOMS.join(', ')}`,
 30	  title: 'title must be 1 to 80 characters',
 31	  date: 'date must be a valid YYYY-MM-DD date',
 32	  start: 'start must be HH:MM',
 33	  end: 'end must be HH:MM',
 34	  order: 'end must be after start',
 35	});
 36	
 37	class HttpError extends Error {
 38	  constructor(status, message) {
 39	    super(message);
 40	    this.status = status;
 41	  }
 42	}
 43	
 44	// ---------- field validation (pure) ----------
 45	
 46	const DATE_RE = /^([0-9]{4})-([0-9]{2})-([0-9]{2})$/;
 47	const TIME_RE = /^(?:[01][0-9]|2[0-3]):[0-5][0-9]$/;
 48	
 49	function isValidDate(value) {
 50	  if (typeof value !== 'string') return false;
 51	  const match = DATE_RE.exec(value);
 52	  if (!match) return false;
 53	  const [year, month, day] = match.slice(1).map(Number);
 54	  if (year < 2000 || year > 2099 || month < 1 || month > 12 || day < 1) return false;
 55	  const febDays = year % 4 === 0 ? 29 : 28;
 56	  const monthDays = [31, febDays, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
 57	  return day <= monthDays[month - 1];
 58	}
 59	
 60	function isValidTime(value) {
 61	  return typeof value === 'string' && TIME_RE.test(value);
 62	}
 63	
 64	function isValidTitle(value) {
 65	  return typeof value === 'string' && value.length >= 1 && value.length <= 80;
 66	}
 67	
 68	function isPlainObject(value) {
 69	  return typeof value === 'object' && value !== null && !Array.isArray(value);
 70	}
 71	
 72	/** Applies booking rules 4-9 in order; returns the cleaned fields or throws HttpError 400. */
 73	function validateBookingInput(body) {
 74	  if (typeof body.room !== 'string' || !ROOMS.includes(body.room)) throw new HttpError(400, MSG.room);
 75	  const title = typeof body.title === 'string' ? body.title.trim() : undefined;
 76	  if (!isValidTitle(title)) throw new HttpError(400, MSG.title);
 77	  if (!isValidDate(body.date)) throw new HttpError(400, MSG.date);
 78	  if (!isValidTime(body.start)) throw new HttpError(400, MSG.start);
 79	  if (!isValidTime(body.end)) throw new HttpError(400, MSG.end);
 80	  if (!(body.end > body.start)) throw new HttpError(400, MSG.order);
 81	  return { room: body.room, title, date: body.date, start: body.start, end: body.end };
 82	}
 83	
 84	function overlaps(a, b) {
 85	  return a.room === b.room && a.date === b.date && a.start < b.end && b.start < a.end;
 86	}
 87	
 88	function findEarliestOverlap(bookings, candidate) {
 89	  return bookings
 90	    .filter((b) => overlaps(b, candidate))
 91	    .reduce((earliest, b) => (earliest === null || b.start < earliest.start ? b : earliest), null);
 92	}
 93	
 94	function compareBookings(a, b) {
 95	  if (a.date !== b.date) return a.date < b.date ? -1 : 1;
 96	  if (a.start !== b.start) return a.start < b.start ? -1 : 1;
 97	  const byRoom = ROOMS.indexOf(a.room) - ROOMS.indexOf(b.room);
 98	  return byRoom !== 0 ? byRoom : a.id - b.id;
 99	}
100	
101	// ---------- data file ----------
102	
103	function isStoredBooking(value) {
104	  if (!isPlainObject(value)) return false;
105	  const keys = Object.keys(value);
106	  if (keys.length !== BOOKING_KEYS.length || !BOOKING_KEYS.every((k) => keys.includes(k))) return false;
107	  return Number.isSafeInteger(value.id) && value.id >= 1
108	    && ROOMS.includes(value.room)
109	    && isValidTitle(value.title) && value.title === value.title.trim()
110	    && isValidDate(value.date) && isValidTime(value.start) && isValidTime(value.end)
111	    && value.end > value.start;
112	}
113	
114	/** True when `data` is exactly the layout this server writes: {nextId, bookings}. */
115	function isValidStore(data) {
116	  if (!isPlainObject(data)) return false;
117	  const keys = Object.keys(data);
118	  if (keys.length !== 2 || !keys.includes('nextId') || !keys.includes('bookings')) return false;
119	  const { nextId, bookings } = data;
120	  if (!Number.isSafeInteger(nextId) || nextId < 1 || !Array.isArray(bookings)) return false;
121	  if (!bookings.every(isStoredBooking)) return false;
122	  const ids = new Set(bookings.map((b) => b.id));
123	  if (ids.size !== bookings.length || bookings.some((b) => b.id >= nextId)) return false;
124	  return bookings.every((b, i) => bookings.every((other, j) => i === j || !overlaps(b, other)));
125	}
126	
127	function freezeStore(store) {
128	  return Object.freeze({
129	    nextId: store.nextId,
130	    bookings: Object.freeze(store.bookings.map((b) => Object.freeze({ ...b }))),
131	  });
132	}
133	
134	/** Reads the data file synchronously at startup. Returns the store, or null when unreadable. */
135	function loadStore(filePath) {
136	  let text;
137	  try {
138	    text = readFileSync(filePath, 'utf8');
139	  } catch (err) {
140	    if (err && err.code === 'ENOENT') return freezeStore({ nextId: 1, bookings: [] });
141	    return null;
142	  }
143	  try {
144	    const data = JSON.parse(text);
145	    return isValidStore(data) ? freezeStore(data) : null;
146	  } catch {
147	    return null; // invalid JSON is reported by the caller as "cannot read data file"
148	  }
149	}
150	
151	// ---------- state + serialized saves ----------
152	
153	function createRepository(filePath, initialStore) {
154	  let store = initialStore;
155	  let queue = Promise.resolve();
156	
157	  /** Runs `change(store)` -> next store (or an HttpError), saves it, then commits it. One at a time. */
158	  function mutate(change) {
159	    const run = queue.then(async () => {
160	      const next = freezeStore(change(store));
161	      await writeFile(filePath, JSON.stringify(next));
162	      store = next;
163	      return next;
164	    });
165	    queue = run.catch(() => undefined); // keep the chain alive; the caller handles `run`'s rejection
166	    return run;
167	  }
168	
169	  return { current: () => store, mutate };
170	}
171	
172	// ---------- HTTP helpers ----------
173	
174	function sendJson(res, status, payload) {
175	  const body = Buffer.from(JSON.stringify(payload), 'utf8');
176	  res.writeHead(status, { 'Content-Type': JSON_TYPE, 'Content-Length': body.length });
177	  res.end(body);
178	}
179	
180	function sendError(res, status, message) {
181	  sendJson(res, status, { error: message });
182	}
183	
184	/** Reads the whole request body; keeps at most `limit` bytes but counts every byte received. */
185	function readBody(req, limit) {
186	  return new Promise((resolve, reject) => {
187	    const chunks = [];
188	    let size = 0;
189	    req.on('data', (chunk) => {
190	      size += chunk.length;
191	      if (size <= limit) chunks.push(chunk);
192	    });
193	    req.on('end', () => resolve({ size, buffer: size <= limit ? Buffer.concat(chunks) : null }));
194	    req.on('error', reject);
195	  });
196	}
197	
198	function mediaTypeIsJson(header) {
199	  if (typeof header !== 'string') return false;
200	  const media = header.split(';', 1)[0].replace(/^[ \t]+|[ \t]+$/g, '');
201	  return media.replace(/[A-Z]/g, (c) => c.toLowerCase()) === 'application/json';
202	}
203	
204	function parseObjectBody(buffer) {
205	  try {
206	    const value = JSON.parse(buffer.toString('utf8'));
207	    return isPlainObject(value) ? value : null;
208	  } catch {
209	    return null; // not JSON: rule 3 reply is decided by the caller
210	  }
211	}
212	
213	// ---------- route handlers ----------
214	
215	function listBookings(repo, query) {
216	  const params = new URLSearchParams(query);
217	  const all = repo.current().bookings;
218	  if (!params.has('date')) return [...all].sort(compareBookings);
219	  const date = params.get('date');
220	  if (!isValidDate(date)) throw new HttpError(400, MSG.date);
221	  return all.filter((b) => b.date === date).sort(compareBookings);
222	}
223	
224	async function createBooking(repo, req, body) {
225	  if (!mediaTypeIsJson(req.headers['content-type'])) throw new HttpError(415, MSG.contentType);
226	  if (body.size > MAX_BODY_BYTES) throw new HttpError(413, MSG.tooLarge);
227	  const parsed = parseObjectBody(body.buffer);
228	  if (parsed === null) throw new HttpError(400, MSG.notObject);
229	  const fields = validateBookingInput(parsed);
230	  const next = await repo.mutate((store) => {
231	    const clash = findEarliestOverlap(store.bookings, fields);
232	    if (clash) throw new HttpError(409, `room is already booked from ${clash.start} to ${clash.end}`);
233	    return { nextId: store.nextId + 1, bookings: [...store.bookings, { id: store.nextId, ...fields }] };
234	  });
235	  return next.bookings.at(-1);
236	}
237	
238	const bookingNotFound = () => new HttpError(404, MSG.bookingNotFound);
239	
240	async function deleteBooking(repo, idText) {
241	  if (!/^[1-9][0-9]*$/.test(idText)) throw bookingNotFound();
242	  await repo.mutate((store) => {
243	    const remaining = store.bookings.filter((b) => String(b.id) !== idText);
244	    if (remaining.length === store.bookings.length) throw bookingNotFound();
245	    return { nextId: store.nextId, bookings: remaining };
246	  });
247	}
248	
249	async function serveStatic(res, file) {
250	  const content = await readFile(file.url);
251	  res.writeHead(200, { 'Content-Type': file.type, 'Content-Length': content.length });
252	  res.end(content);
253	}
254	
255	// ---------- routing ----------
256	
257	function splitTarget(target) {
258	  const at = target.indexOf('?');
259	  return at === -1 ? { pathname: target, query: '' } : { pathname: target.slice(0, at), query: target.slice(at + 1) };
260	}
261	
262	/** Maps a raw path to a route name and parameter; null when no route matches. */
263	function matchRoute(pathname) {
264	  if (pathname === '/api/rooms') return { name: 'rooms', methods: ['GET'] };
265	  if (pathname === '/api/bookings') return { name: 'bookings', methods: ['GET', 'POST'] };
266	  if (Object.hasOwn(STATIC_FILES, pathname)) return { name: 'static', methods: ['GET'] };
267	  if (pathname.startsWith(BOOKINGS_PREFIX)) {
268	    const id = pathname.slice(BOOKINGS_PREFIX.length);
269	    if (id !== '' && !id.includes('/')) return { name: 'booking', methods: ['DELETE'], id };
270	  }
271	  return null;
272	}
273	
274	async function dispatch(repo, req, res, body) {
275	  const { pathname, query } = splitTarget(req.url);
276	  const route = matchRoute(pathname);
277	  if (route === null) throw new HttpError(404, MSG.notFound);
278	  if (!route.methods.includes(req.method)) throw new HttpError(405, MSG.method);
279	  if (route.name === 'rooms') return sendJson(res, 200, { rooms: ROOMS });
280	  if (route.name === 'static') return serveStatic(res, STATIC_FILES[pathname]);
281	  if (route.name === 'booking') {
282	    await deleteBooking(repo, route.id);
283	    res.writeHead(204);
284	    return res.end();
285	  }
286	  if (req.method === 'GET') return sendJson(res, 200, { bookings: listBookings(repo, query) });
287	  return sendJson(res, 201, await createBooking(repo, req, body));
288	}
289	
290	function createHandler(repo) {
291	  return async function handleRequest(req, res) {
292	    try {
293	      const body = await readBody(req, MAX_BODY_BYTES);
294	      await dispatch(repo, req, res, body);
295	    } catch (err) {
296	      replyWithError(res, err);
297	    }
298	  };
299	}
300	
301	function replyWithError(res, err) {
302	  try {
303	    if (res.headersSent) return res.destroy();
304	    if (err instanceof HttpError) return sendError(res, err.status, err.message);
305	    return sendError(res, 500, MSG.internal);
306	  } catch {
307	    return res.destroy(); // the reply itself failed; drop the connection rather than crash
308	  }
309	}
310	
311	/** CONNECT bypasses the request handler; answer it on the raw socket (no route allows it). */
312	function handleConnect(req, socket) {
313	  const route = matchRoute(splitTarget(req.url).pathname);
314	  const [status, reason, message] = route === null
315	    ? [404, 'Not Found', MSG.notFound]
316	    : [405, 'Method Not Allowed', MSG.method];
317	  const body = Buffer.from(JSON.stringify({ error: message }), 'utf8');
318	  const head = `HTTP/1.1 ${status} ${reason}\r\nContent-Type: ${JSON_TYPE}\r\n`
319	    + `Content-Length: ${body.length}\r\nConnection: close\r\n\r\n`;
320	  socket.on('error', () => socket.destroy()); // client went away; nothing left to answer
321	  socket.end(Buffer.concat([Buffer.from(head, 'latin1'), body]));
322	}
323	
324	// ---------- startup ----------
325	
326	function fail(line) {
327	  process.stderr.write(`${line}\n`);
328	  process.exit(1);
329	}
330	
331	function parsePort(raw) {
332	  if (raw === undefined || raw === '') return DEFAULT_PORT;
333	  if (!/^[0-9]+$/.test(raw)) return null;
334	  const port = Number(raw);
335	  return port <= 65535 ? port : null;
336	}
337	
338	function start() {
339	  const port = parsePort(process.env.PORT);
340	  if (port === null) fail(`invalid PORT ${JSON.stringify(process.env.PORT)}`);
341	
342	  const dataName = process.env.DATA_FILE ? process.env.DATA_FILE : DEFAULT_DATA_FILE;
343	  const dataPath = path.resolve(process.cwd(), dataName);
344	  const store = loadStore(dataPath);
345	  if (store === null) fail(`cannot read data file ${dataName}`);
346	
347	  const repo = createRepository(dataPath, store);
348	  const handler = createHandler(repo);
349	  const server = http.createServer({ requireHostHeader: false }, handler);
350	  server.on('checkExpectation', handler);
351	  server.on('connect', handleConnect);
352	  let listening = false;
353	  server.on('error', (err) => {
354	    if (!listening) fail(`cannot listen on port ${port}: ${err.code || 'error'}`);
355	    process.stderr.write(`server error: ${err.code || 'error'}\n`);
356	  });
357	  server.listen(port, HOST, () => {
358	    listening = true;
359	    process.stdout.write(`listening on http://${HOST}:${server.address().port}\n`);
360	  });
361	}
362	
363	start();

  1	(function () {
  2	  'use strict';
  3	
  4	  const NO_REPLY = 'Could not reach the server.';
  5	  const REQUEST_FAILED = 'Request failed.';
  6	
  7	  const form = document.getElementById('booking-form');
  8	  const roomSelect = document.getElementById('room');
  9	  const titleInput = document.getElementById('title');
 10	  const dateInput = document.getElementById('date');
 11	  const startInput = document.getElementById('start');
 12	  const endInput = document.getElementById('end');
 13	  const bookButton = document.getElementById('book');
 14	  const filterDate = document.getElementById('filter-date');
 15	  const showAllButton = document.getElementById('show-all');
 16	  const bookingList = document.getElementById('booking-list');
 17	  const errorBox = document.getElementById('error');
 18	
 19	  let latestListRequest = 0;
 20	
 21	  // Resolves to { status, body } or to null when there is no usable reply.
 22	  // onSettle runs as soon as the reply and its body have arrived, or the
 23	  // request failed, before the caller sees the outcome.
 24	  async function send(url, options, onSettle) {
 25	    try {
 26	      const response = await fetch(url, options);
 27	      if (response.status === 204) {
 28	        return { status: 204, body: undefined };
 29	      }
 30	      const body = await response.json();
 31	      return { status: response.status, body: body };
 32	    } catch {
 33	      // fetch rejected, or a non-204 body was not readable JSON: no reply.
 34	      return null;
 35	    } finally {
 36	      if (onSettle) {
 37	        onSettle();
 38	      }
 39	    }
 40	  }
 41	
 42	  function isPlainObject(value) {
 43	    return typeof value === 'object' && value !== null && !Array.isArray(value);
 44	  }
 45	
 46	  function errorMessage(body) {
 47	    if (isPlainObject(body) && typeof body.error === 'string') {
 48	      return body.error;
 49	    }
 50	    return REQUEST_FAILED;
 51	  }
 52	
 53	  function showError(text) {
 54	    errorBox.textContent = text;
 55	  }
 56	
 57	  function createOption(room) {
 58	    const option = document.createElement('option');
 59	    option.value = room;
 60	    option.textContent = room;
 61	    return option;
 62	  }
 63	
 64	  async function loadRooms() {
 65	    const reply = await send('/api/rooms', { method: 'GET' });
 66	    if (reply === null) {
 67	      showError(NO_REPLY);
 68	      return;
 69	    }
 70	    if (reply.status !== 200) {
 71	      showError(errorMessage(reply.body));
 72	      return;
 73	    }
 74	    if (!isPlainObject(reply.body) || !Array.isArray(reply.body.rooms)) {
 75	      showError(REQUEST_FAILED);
 76	      return;
 77	    }
 78	    roomSelect.replaceChildren(...reply.body.rooms.map(createOption));
 79	  }
 80	
 81	  function bookingText(booking) {
 82	    return booking.date + ' ' + booking.start + '-' + booking.end + ' ' +
 83	      booking.room + ': ' + booking.title;
 84	  }
 85	
 86	  function createBookingItem(booking) {
 87	    const item = document.createElement('li');
 88	    const cancelButton = document.createElement('button');
 89	    cancelButton.type = 'button';
 90	    cancelButton.textContent = 'Cancel';
 91	    cancelButton.addEventListener('click', function () {
 92	      cancelBooking(booking.id, cancelButton);
 93	    });
 94	    item.append(bookingText(booking), cancelButton);
 95	    return item;
 96	  }
 97	
 98	  function createEmptyItem() {
 99	    const item = document.createElement('li');
100	    item.append('No bookings.');
101	    return item;
102	  }
103	
104	  function listUrl() {
105	    const date = filterDate.value;
106	    return date === '' ? '/api/bookings' : '/api/bookings?date=' + date;
107	  }
108	
109	  async function loadList() {
110	    latestListRequest += 1;
111	    const requestNumber = latestListRequest;
112	    const reply = await send(listUrl(), { method: 'GET' });
113	    if (requestNumber !== latestListRequest) {
114	      return;
115	    }
116	    if (reply === null) {
117	      showError(NO_REPLY);
118	      return;
119	    }
120	    if (reply.status !== 200) {
121	      showError(errorMessage(reply.body));
122	      return;
123	    }
124	    if (!isPlainObject(reply.body) || !Array.isArray(reply.body.bookings) ||
125	        !reply.body.bookings.every(isPlainObject)) {
126	      showError(REQUEST_FAILED);
127	      return;
128	    }
129	    const bookings = reply.body.bookings;
130	    const items = bookings.length === 0
131	      ? [createEmptyItem()]
132	      : bookings.map(createBookingItem);
133	    bookingList.replaceChildren(...items);
134	  }
135	
136	  async function cancelBooking(id, cancelButton) {
137	    cancelButton.disabled = true;
138	    const reply = await send('/api/bookings/' + id, { method: 'DELETE' }, function () {
139	      cancelButton.disabled = false;
140	    });
141	    if (reply === null) {
142	      showError(NO_REPLY);
143	      return;
144	    }
145	    showError(reply.status === 204 ? '' : errorMessage(reply.body));
146	    loadList();
147	  }
148	
149	  function bookingPayload() {
150	    return {
151	      room: roomSelect.value,
152	      title: titleInput.value,
153	      date: dateInput.value,
154	      start: startInput.value,
155	      end: endInput.value
156	    };
157	  }
158	
159	  async function submitBooking() {
160	    bookButton.disabled = true;
161	    const options = {
162	      method: 'POST',
163	      headers: { 'Content-Type': 'application/json' },
164	      body: JSON.stringify(bookingPayload())
165	    };
166	    const reply = await send('/api/bookings', options, function () {
167	      bookButton.disabled = false;
168	    });
169	    if (reply === null) {
170	      showError(NO_REPLY);
171	      return;
172	    }
173	    if (reply.status !== 201) {
174	      showError(errorMessage(reply.body));
175	      return;
176	    }
177	    titleInput.value = '';
178	    showError('');
179	    loadList();
180	  }
181	
182	  form.addEventListener('submit', function (event) {
183	    event.preventDefault();
184	    if (bookButton.disabled) {
185	      return;
186	    }
187	    submitBooking();
188	  });
189	
190	  filterDate.addEventListener('change', function () {
191	    loadList();
192	  });
193	
194	  showAllButton.addEventListener('click', function () {
195	    filterDate.value = '';
196	    loadList();
197	  });
198	
199	  loadRooms();
200	  loadList();
201	}());
202	<!DOCTYPE html>
203	<html lang="en">
204	<head>
205	<meta charset="utf-8">
206	<meta name="viewport" content="width=device-width, initial-scale=1">
207	<title>Room bookings</title>
208	<style>
209	  :root { color-scheme: light dark; font-family: system-ui, sans-serif; }
210	  body { max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; }
211	  form, .filter { display: grid; grid-template-columns: max-content 1fr; gap: 0.5rem 1rem; align-items: center; margin-bottom: 1.5rem; }
212	  form button { grid-column: 2; justify-self: start; }
213	  .filter button { grid-column: 2; justify-self: start; }
214	  input, select, button { font: inherit; padding: 0.25rem 0.5rem; }
215	  button:disabled { opacity: 0.6; cursor: not-allowed; }
