test('harness smoke', async () => {
  const r = await request(ctx.port, { path: '/api/rooms' });
  assert.equal(r.status, 200);
  const p = await postBooking(ctx.port, VALID_BOOKING);
  assert.equal(p.status, 201);
  const raw = await rawRequest(ctx.port, 'GET /api/./rooms HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n');
  assert.match(raw, /^HTTP\/1.1 404/);
});

